// Save to Knowledger - one click on the LinkedIn post you are viewing.
// config.js (generated by `python3 linkedin_capture.py --init`) defines CAPTURE_URL and CAPTURE_TOKEN.
importScripts('config.js');

const MAX_IMAGES = 20;
const MAX_IMAGE_BYTES = 10 * 1024 * 1024;

// Runs INSIDE the page: a visible message so errors can be read without opening DevTools.
function pageToast(msg, color) {
  const id = '__knowledger_toast__';
  const old = document.getElementById(id);
  if (old) old.remove();
  const d = document.createElement('div');
  d.id = id;
  d.textContent = msg;
  d.style.cssText = 'position:fixed;z-index:2147483647;top:16px;right:16px;max-width:380px;padding:12px 14px;' +
    'border-radius:8px;font:14px/1.4 system-ui,sans-serif;color:#fff;box-shadow:0 4px 16px rgba(0,0,0,.35);background:' + color;
  document.body.appendChild(d);
  setTimeout(() => d.remove(), 12000);
}

// Errors stay on the icon until the next click; successes clear after 6 seconds.
async function badge(tabId, text, color, title, persist) {
  chrome.action.setBadgeText({ tabId, text });
  chrome.action.setBadgeBackgroundColor({ tabId, color });
  if (title) chrome.action.setTitle({ tabId, title });
  if (title && text !== '...') {
    try {
      await chrome.scripting.executeScript({ target: { tabId }, func: pageToast, args: [title, color] });
    } catch (e) { /* page not scriptable; icon still shows the state */ }
  }
  if (!persist) {
    setTimeout(() => {
      chrome.action.setBadgeText({ tabId, text: '' });
      chrome.action.setTitle({ tabId, title: 'Save this LinkedIn post to Knowledger' });
    }, 6000);
  }
}

// Distinguish "server not running" from "server said no".
async function serverUp() {
  try {
    const r = await fetch(CAPTURE_URL.replace(/\/capture$/, '/health'));
    return r.ok;
  } catch (e) { return false; }
}

async function blobToB64(blob) {
  const buf = new Uint8Array(await blob.arrayBuffer());
  let s = '';
  const CH = 0x8000;
  for (let i = 0; i < buf.length; i += CH) s += String.fromCharCode.apply(null, buf.subarray(i, i + CH));
  return btoa(s);
}

// Runs INSIDE the LinkedIn page (injected with chrome.scripting.executeScript).
// It must be self-contained. LinkedIn scrambles its CSS class names, so this relies on
// structure (data-testid, document order, ancestors) instead of classes, and everything is
// scoped to the post itself: the page also contains YOUR profile card, ads and suggestions,
// which must never be mistaken for the post.
async function extractPost() {
  const here = location.href;
  if (!/linkedin\.com\/(posts\/|feed\/update\/|pulse\/)/.test(here)) {
    return { error: 'Open the post on its own page (click its timestamp), then try again.' };
  }
  const canonical = document.querySelector('link[rel="canonical"]');
  const url = (canonical && /linkedin\.com\/(posts\/|feed\/update\/|pulse\/)/.test(canonical.href)) ? canonical.href : here;
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));

  const COMMENT_SEL = '[class*="comment"], [data-view-name*="comment"], [data-testid*="comment"], section[aria-label*="omment"]';
  const SPECIFIC_TEXT = [
    '[data-view-name="feed-commentary"]',
    '[data-testid="expandable-text-box"]',
    '.update-components-text',
    '.feed-shared-update-v2__description',
    '.feed-shared-text',
    '[data-test-id="main-feed-activity-card__commentary"]',
    '.attributed-text-segment-list__content',
    '.article-content'
  ];

  // 1) The post's text element = the first text block in document order (comments come after the post).
  let firstTextEl = null;
  for (const el of document.querySelectorAll(SPECIFIC_TEXT.join(','))) {
    if (((el.innerText || '').trim()).length > 10) { firstTextEl = el; break; }
  }

  // An element is "in comments" only if its comment-ish ancestor does NOT also contain the post text.
  // (LinkedIn names the whole post wrapper "...commentList...", which must not count as a comment.)
  const inComments = (el) => {
    const c = el.closest(COMMENT_SEL);
    return !!c && !(firstTextEl && c.contains(firstTextEl));
  };
  const notComment = (sel) => Array.from(document.querySelectorAll(sel)).find(e => !inComments(e)) || null;

  // 2) The post container: climb from the text until the ancestor also holds the post's media,
  //    reaction bar or comment box. Never the whole <main> (that includes your own profile card).
  let root = null, rootHow = '';
  if (firstTextEl) {
    let n = firstTextEl.parentElement;
    for (let i = 1; i <= 14 && n && n !== document.body; i++, n = n.parentElement) {
      if (n.tagName === 'MAIN') break;
      if (n.querySelector('video, [data-testid^="ReactionFacepileCollection"], [data-testid^="ui-core-tiptap"]')) {
        root = n; rootHow = 'climb@' + i; break;
      }
    }
  }
  if (!root) {
    root = notComment('[data-view-name="feed-full-update"]') || notComment('.feed-shared-update-v2') ||
           notComment('[data-urn^="urn:li:activity"]') || notComment('article');
    rootHow = root ? 'known-container' : '';
  }
  if (!root) {
    root = document.querySelector('main') || document.body;
    rootHow = 'fallback-main (author/images may be unreliable)';
  }
  const rootIsReliable = rootHow !== '' && rootHow.indexOf('fallback') !== 0;

  // 3) Expand a truncated post ("...more"), as a person would. At most 3 buttons.
  let clicked = 0;
  for (const b of root.querySelectorAll('button')) {
    const t = (b.innerText || '').trim();
    if (clicked < 3 && /^(…|\.\.\.)?\s*(see more|more)$/i.test(t)) {
      try { b.click(); clicked++; } catch (e) {}
    }
  }
  if (clicked) await sleep(500);

  // 4) Comments load lazily: briefly bring the comment box into view (like scrolling down),
  //    open "load more comments" if present, then put the page back where it was.
  const startX = window.scrollX, startY = window.scrollY;
  let loadClicks = 0, scrolled = false;
  try {
    const ed = document.querySelector('[data-testid^="ui-core-tiptap-text-editor-wrapper"]');
    if (ed) { ed.scrollIntoView({ block: 'center' }); scrolled = true; await sleep(1200); }
    for (const b of document.querySelectorAll('button')) {
      const t = (b.innerText || '').trim();
      if (loadClicks < 2 && /^(load|show|see|view) (more|previous|all) (comments|replies)/i.test(t)) {
        try { b.click(); loadClicks++; } catch (e) {}
      }
    }
    if (loadClicks) await sleep(1200);
  } catch (e) { /* best effort */ } finally { window.scrollTo(startX, startY); }

  // 5) Post text.
  let text = '', textSource = '', textEl = null;
  if (firstTextEl) {
    // re-read after expansion
    text = (firstTextEl.innerText || '').trim();
    textEl = firstTextEl;
    textSource = SPECIFIC_TEXT.find(s => { try { return firstTextEl.matches(s); } catch (e) { return false; } }) || 'first-text-block';
  }
  if (!text) {
    const sel = String(window.getSelection() || '').trim();
    if (sel.length > 10) { text = sel; textSource = 'user-selection'; }
  }
  if (!text) {
    let best = '', bestEl = null;
    for (const el of root.querySelectorAll('[dir="ltr"], p')) {
      if (inComments(el)) continue;
      const t = (el.innerText || '').trim();
      if (t.length > best.length && t.length < 8000 && el.querySelectorAll('img, button').length < 3) { best = t; bestEl = el; }
    }
    if (best.length > 30) { text = best; textSource = 'heuristic:longest-dir-ltr (verify)'; textEl = bestEl; }
  }
  if (!text) {
    const og = document.querySelector('meta[property="og:description"]');
    text = (og && og.content) || '';
    textSource = text ? 'og:description (may be truncated)' : 'none-found';
  }

  // 6) Author: the first profile/company link WITH visible text inside the post, before the text.
  let author = '';
  const known = root.querySelector('[data-view-name="feed-actor-name"]') ||
                root.querySelector('.update-components-actor__title [aria-hidden="true"]') ||
                root.querySelector('.update-components-actor__name');
  if (known && known.innerText) author = known.innerText.trim().split('\n')[0];
  if (!author && rootIsReliable) {
    for (const l of root.querySelectorAll('a[href*="/in/"], a[href*="/company/"], a[href*="/school/"]')) {
      if (inComments(l)) continue;
      if (textEl && !(l.compareDocumentPosition(textEl) & Node.DOCUMENT_POSITION_FOLLOWING)) continue;
      const t = (l.innerText || '').trim().split('\n')[0];
      if (t && t.length < 80) { author = t; break; }
    }
  }
  if (!author) {
    const ogt = document.querySelector('meta[property="og:title"]');
    if (ogt && ogt.content) author = ogt.content.split(' on LinkedIn')[0].split(' | ')[0].trim();
  }

  // 7) Images from the post only. Skip small images, wide banners/ad strips, avatars and logos.
  const seen = new Set();
  const imageUrls = [];
  const posterUrls = [];   // LinkedIn's static preview frame of a video
  for (const img of root.querySelectorAll('img')) {
    if (inComments(img)) continue;
    const s = img.currentSrc || img.src || '';
    const w = img.naturalWidth || img.width || 0;
    const h = img.naturalHeight || img.height || 0;
    const banner = h > 0 && w / h > 2.8;
    if (/licdn\.com\/dms\/image/.test(s) &&
        !/profile-displayphoto|profile-framedphoto|profile-displaybackgroundimage|background|banner|company-logo|logo_/.test(s) &&
        w >= 300 && !banner && !seen.has(s)) {
      seen.add(s);
      imageUrls.push(s);
      if (/videocover|video-cover/i.test(s) || img.closest('.vjs-poster, [class*="vjs-poster"], [class*="poster"]')) posterUrls.push(s);
    }
  }

  // 8) Video: it usually streams from a blob, so the file cannot be saved from here. Record that it exists.
  const hasVideo = !!root.querySelector('video, .vjs-control-bar, [class*="video-player"], [data-view-name*="video"], [data-testid*="video"]');
  const videos = Array.from(root.querySelectorAll('video')).slice(0, 3).map(v => {
    const s = v.currentSrc || v.src || '';
    let host = '', path = '';
    try { const u = new URL(s, location.href); host = u.protocol === 'blob:' ? 'blob' : u.host; path = u.protocol === 'blob:' ? '' : u.pathname.slice(0, 60); } catch (e) {}
    return { srcKind: s.startsWith('blob:') ? 'blob' : (s ? 'url' : 'none'), host, path };
  });

  // 8b) Stream addresses. LinkedIn plays video from a blob: URL, but the real files (an .m3u8/.mpd
  //     playlist or an .mp4) show up in the page's resource list once playback starts. The local
  //     receiver downloads them with ffmpeg. If none are seen yet, play the video muted for a moment.
  const STREAM_RE = /licdn\.com\/.*(\.m3u8|\.mpd|\.mp4|\/playlist\/vid\/|\/vid\/)/i;
  const readStreams = () => {
    const out = [];
    try {
      for (const e of performance.getEntriesByType('resource')) {
        if (STREAM_RE.test(e.name) && !out.includes(e.name)) out.push(e.name);
        if (out.length >= 800) break;
      }
    } catch (err) {}
    return out;
  };
  let videoCandidates = [];
  let playedForProbe = false;
  if (hasVideo) {
    try { performance.setResourceTimingBufferSize(2000); } catch (err) {}
    videoCandidates = readStreams();
    const v = root.querySelector('video');
    if (v) {
      // The player only fetches a few fragments ahead. Play the whole thing muted at top speed so
      // every fragment is requested (and therefore listed), then put the player back as it was.
      const t0 = v.currentTime, wasPaused = v.paused, wasMuted = v.muted, wasRate = v.playbackRate;
      try {
        v.muted = true; v.playbackRate = 16; v.currentTime = 0;
        await v.play();
        playedForProbe = true;
        const started = Date.now();
        while (Date.now() - started < 60000 && !v.ended && !(isFinite(v.duration) && v.currentTime >= v.duration - 0.3)) {
          await sleep(300);
        }
        await sleep(1000);
      } catch (err) { /* autoplay blocked etc.: use what was already seen */ }
      try { v.pause(); v.playbackRate = wasRate; v.muted = wasMuted; v.currentTime = t0; if (!wasPaused) v.play().catch(() => {}); } catch (err) {}
      videoCandidates = readStreams();
    }
  }

  // 9) External links: post body, attachments and comments (a "link in the comments").
  //    LinkedIn wraps outbound links in /redir/redirect?url=... and /safety/go/?url=...
  const unwrap = (h) => {
    try {
      const u = new URL(h, location.href);
      if (/(^|\.)linkedin\.com$/.test(u.hostname) && (u.pathname.indexOf('/redir/') === 0 || u.pathname.indexOf('/safety/go') === 0)) {
        const t = u.searchParams.get('url');
        if (t) return t;
      }
      return u.href;
    } catch (e) { return null; }
  };
  const scope = document.querySelector('main') || document.body;
  const links = [];
  const seenLinks = new Set();
  for (const a of scope.querySelectorAll('a[href]')) {
    const u = unwrap(a.getAttribute('href') || '');
    if (!u || !/^https?:/i.test(u) || seenLinks.has(u)) continue;
    let host = '';
    try { host = new URL(u).hostname; } catch (e) { continue; }
    if (/(^|\.)(linkedin|licdn)\.com$/.test(host)) continue;
    seenLinks.add(u);
    const inPost = !!(textEl && textEl.contains(a));
    const where = inPost ? 'post' : (inComments(a) ? 'comment' : (root.contains(a) ? 'post' : 'page'));
    let by = '';
    if (where === 'comment' || where === 'page') {
      const cont = a.closest('[class*="comment"], [data-view-name*="comment"], [data-testid*="comment"], article, [role="listitem"]');
      const p = cont && cont.querySelector('a[href*="/in/"], a[href*="/company/"]');
      by = ((p && p.innerText) || '').trim().split('\n')[0].slice(0, 60);
    }
    const ctxEl = a.closest('p, span, div') || a;
    links.push({ url: u, where, by, anchor: (a.innerText || '').trim().slice(0, 80), context: (ctxEl.innerText || '').trim().slice(0, 160) });
    if (links.length >= 30) break;
  }

  // 10) When something could not be found, describe what IS on the page so the selectors can be fixed.
  //     Structure only, plus the first 50 characters of a few text blocks; saved locally.
  let diagnostics = null;
  if (!text || !author || !rootIsReliable || /^(heuristic|og:|none)/.test(textSource) || hasVideo || links.length === 0 || imageUrls.length === 0) {
    const describe = (el) => {
      const t = (el.innerText || '').trim();
      return {
        tag: el.tagName.toLowerCase(),
        testid: (el.getAttribute('data-testid') || '').slice(0, 60),
        role: el.getAttribute('role'),
        dir: el.getAttribute('dir'),
        href: el.tagName === 'A' ? (el.getAttribute('href') || '').slice(0, 70) : undefined,
        len: t.length,
        sample: t.slice(0, 50)
      };
    };
    const inside = [];
    for (const el of root.querySelectorAll('[data-testid],[role],[dir="ltr"],p,a[href*="/in/"],a[href*="/company/"]')) {
      if (inside.length >= 60) break;
      inside.push(describe(el));
    }
    const below = [];
    for (const el of scope.querySelectorAll('a[href], [dir="ltr"], p, [role="listitem"], article')) {
      if (below.length >= 50) break;
      if (root.contains(el)) continue;
      if (!(root.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_FOLLOWING)) continue;
      if (!((el.innerText || '').trim())) continue;
      below.push(describe(el));
    }
    // Every media-like element around the post (the post may be wider than `root`), so a GIF or
    // lazy-loaded picture that was skipped can be identified. URLs are cut before the query string.
    const mediaScope = (root.parentElement && root.parentElement.parentElement) || root;
    const media = [];
    for (const el of mediaScope.querySelectorAll('img, video, source, picture, canvas, iframe, [style*="background-image"]')) {
      if (media.length >= 40) break;
      const r = el.getBoundingClientRect();
      const u = (el.currentSrc || el.src || el.getAttribute('data-delayed-url') || el.getAttribute('data-src') || '').split('?')[0];
      media.push({
        tag: el.tagName.toLowerCase(),
        src: u.slice(0, 110),
        kind: u.startsWith('blob:') ? 'blob' : (u.startsWith('data:') ? 'data' : (u ? 'url' : 'none')),
        w: el.naturalWidth || el.videoWidth || 0, h: el.naturalHeight || el.videoHeight || 0,
        box: Math.round(r.width) + 'x' + Math.round(r.height),
        loading: el.getAttribute('loading'), alt: (el.getAttribute('alt') || '').slice(0, 40),
        cls: (el.getAttribute('class') || '').slice(0, 50),
        inRoot: root.contains(el), inComment: inComments(el), picked: seen.has(el.currentSrc || el.src || '')
      });
    }
    diagnostics = {
      media,
      path: location.pathname, rootHow, rootTag: root.tagName.toLowerCase(),
      hasVideo, videos, playedForProbe,
      streamCount: videoCandidates.length,
      streamCandidates: videoCandidates.slice(0, 6).map(u => u.split('?')[0].slice(0, 140)),
      scrolledToCommentBox: scrolled, loadMoreClicks: loadClicks,
      counts: {
        commentish: scope.querySelectorAll(COMMENT_SEL).length,
        anchors: scope.querySelectorAll('a[href]').length,
        externalLinks: links.length,
        followingPostInMain: below.length
      },
      inside, below
    };
  }
  return { url, text, textSource, author, imageUrls, posterUrls, pageTitle: document.title, diagnostics, links, hasVideo, videoCandidates };
}

chrome.action.onClicked.addListener(async (tab) => {
  badge(tab.id, '...', '#6b7280');
  try {
    if (!/^https:\/\/([a-z0-9-]+\.)?linkedin\.com\//.test(tab.url || '')) {
      throw new Error('This is not a LinkedIn page.');
    }
    const [injection] = await chrome.scripting.executeScript({ target: { tabId: tab.id }, func: extractPost });
    const post = injection && injection.result;
    if (!post || post.error) throw new Error((post && post.error) || 'Could not read the page.');

    const images = [];
    for (const src of post.imageUrls.slice(0, MAX_IMAGES)) {
      try {
        const r = await fetch(src);
        if (!r.ok) continue;
        const blob = await r.blob();
        if (blob.size > MAX_IMAGE_BYTES) continue;
        images.push({ mime: blob.type || 'image/jpeg', b64: await blobToB64(blob), poster: (post.posterUrls || []).includes(src) });
      } catch (e) { /* skip this image */ }
    }

    const resp = await fetch(CAPTURE_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Capture-Token': CAPTURE_TOKEN },
      body: JSON.stringify({
        url: post.url, author: post.author, text: post.text, text_source: post.textSource,
        images, image_urls_found: post.imageUrls.length, page_title: post.pageTitle,
        diagnostics: post.diagnostics, links_detail: post.links, has_video: post.hasVideo,
        video_candidates: post.videoCandidates || []
      })
    });
    let data = {};
    try { data = await resp.json(); } catch (e) {}
    if (!resp.ok) throw new Error(data.error || ('Server returned HTTP ' + resp.status));

    if (data.status === 'duplicate') {
      badge(tab.id, 'DUP', '#d97706', 'Already saved, nothing new to add: ' + data.note);
    } else if (data.status === 'updated') {
      badge(tab.id, 'UPD', '#16a34a', 'Updated ' + data.note + ': added ' + data.links_added + ' new link(s)');
    } else {
      const warn = (data.warnings && data.warnings.length) ? ' (' + data.warnings.join(' ') + ')' : '';
      badge(tab.id, data.warnings && data.warnings.length ? 'OK!' : 'OK', '#16a34a',
            'Saved: ' + data.note + ' - ' + data.images_saved + ' image(s)' + warn);
    }
  } catch (e) {
    console.error('Save to Knowledger failed:', e);
    let msg = String((e && e.message) || e);
    if (/Failed to fetch|NetworkError/i.test(msg)) {
      msg = (await serverUp())
        ? 'Could not send to the capture server (it is running, but the request failed). ' + msg
        : 'Capture server not running at ' + CAPTURE_URL + '. Restart the bot, or run: python3 linkedin_capture.py';
    } else if (/bad token/i.test(msg)) {
      msg = 'Token mismatch. Run `python3 linkedin_capture.py --init`, then reload this extension.';
    }
    badge(tab.id, 'ERR', '#dc2626', 'Save to Knowledger: ' + msg, true);
  }
});
